@rendermode InteractiveServer
@inject WarehouseState Warehouse
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select" class="form-label mb-0 me-2 text-nowrap">Warehouse:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            value="@Warehouse.SelectedWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseState.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        Warehouse.OnChange += _handler;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            Warehouse.SetWarehouse(warehouseId);
        }
    }

    public void Dispose()
    {
        Warehouse.OnChange -= _handler;
    }
}

