    {
        AlertService.OnAlertCountChanged -= _handler;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard - @Warehouse.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-4">
    <div class="card-body">
        <h5 class="card-title">Currently viewing: @Warehouse.SelectedWarehouseName</h5>
        <p class="card-text">
            Use the warehouse selector in the top bar to switch between warehouses.
            All components on this page will update automatically.
        </p>
    </div>
</div>

<div class="card mt-4">
    <div class="card-body">
        <h5 class="card-title">
            Low Stock Alerts
            <span class="badge bg-danger rounded-pill ms-2">@AlertService.CurrentLowStockCount</span>
        </h5>
        <p class="card-text text-muted">
            Polling every 10 seconds for items below minimum stock levels in <strong>@Warehouse.SelectedWarehouseName</strong>.
        </p>
        <p class="card-text">
            @if (AlertService.CurrentLowStockCount == 0)
            {
                <span class="text-success">✓ All items are above minimum stock levels.</span>
            }
            else
            {
                <span class="text-warning">⚠ @AlertService.CurrentLowStockCount item(s) are below minimum stock levels and require attention.</span>
            }
        </p>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        Warehouse.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;

        // Start polling when this page becomes visible
        AlertService.Subscribe();
    }

    public void Dispose()
    {
        // Stop polling when user leaves this page
        AlertService.Unsubscribe();

        Warehouse.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

